var a=`0762-mandazi`;var i=`world-0762`;var t=`KE`;var s=`eastern-africa`;var o=8;var r=100;var l={en:`Mandazi`,ua:`Мандазі`};var d={en:`Mandazi is a Kenya classic prepared with all-purpose flour, coconut milk, instant yeast. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мандазі, страва кухні країни Кенія зі складниками: пшеничне борошно універсальне, кокосове молоко, інстантні дріжджі. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`all-purpose-flour`,480,`g`],[`coconut-milk`,260,`ml`],[`white-granulated-sugar`,90,`g`],[`instant-yeast`,7,`g`],[`ground-cardamom`,4,`g`],[`table-salt`,4,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 22 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 22 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:22,i:[[`sunflower-oil`,750,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,30,`g`]]}];var g={slug:a,id:i,country:`KE`,region:s,servings:8,minutes:100,title:l,text:d,steps:u};export{t as country,g as default,i as id,r as minutes,s as region,o as servings,a as slug,u as steps,d as text,l as title};